import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';

function Dashboard() {
  const navigate = useNavigate();
  const [counts, setCounts] = useState({ pending: 0, working: 0, resolved: 0, completed: 0 });
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetch('http://localhost:5000/api/issues')
      .then((res) => res.json())
      .then((response) => {
        if (response.success && Array.isArray(response.data)) {
          const issues = response.data;
          const newCounts = { pending: 0, working: 0, resolved: 0, completed: 0 };
          issues.forEach((issue) => {
            const status = issue.status?.toLowerCase();
            if (newCounts[status] !== undefined) {
              newCounts[status]++;
            }
          });
          setCounts(newCounts);
        }
        setLoading(false);
      })
      .catch((err) => {
        console.error('Error fetching issues:', err);
        setLoading(false);
      });
  }, []);

  return (
    <div className="dashboard-page">
      <header className="dashboard-header">
        <h1>Good day, Student!</h1>
        <button onClick={() => navigate('/report')} className="btn-primary">
          + Report an issue
        </button>
      </header>

      {loading ? (
        <p>Loading summary...</p>
      ) : (
        <div className="metrics-grid">
          <div className="metric-card">
            <h3>{counts.pending}</h3>
            <p>Pending</p>
          </div>
          <div className="metric-card">
            <h3>{counts.working}</h3>
            <p>Working</p>
          </div>
          <div className="metric-card">
            <h3>{counts.resolved}</h3>
            <p>Resolved</p>
          </div>
          <div className="metric-card">
            <h3>{counts.completed}</h3>
            <p>Completed</p>
          </div>
        </div>
      )}
    </div>
  );
}

export default Dashboard;
